contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 depositAmount, uint256 betLimitAmount, uint256 difficultyAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        c.AdjustBetAmounts(betLimitAmount); if (__ESBMC_reverted()) return;
        c.AdjustDifficulty(difficultyAmount); if (__ESBMC_reverted()) return;
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;

        c.donate{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint256 afterBalance = c.ethBalance(); if (__ESBMC_reverted()) return;

        assert(afterBalance == address(c).balance);
    }

    receive() external payable {}
}

