pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 depositAmount, uint256 betLimitAmount, uint256 difficultyAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.AdjustBetAmounts(betLimitAmount) {} catch { return; }
        try c.AdjustDifficulty(difficultyAmount) {} catch { return; }
        try c.OpenToThePublic() {} catch { return; }
        try c.donate{value: depositAmount}() {} catch { return; }
        uint256 afterBalance;
        try c.ethBalance() returns (uint256 __r) { afterBalance = __r; } catch { return; }
        assertTrue(afterBalance == address(c).balance);
    }

    function testFuzz_run(uint256 depositAmount, uint256 betLimitAmount, uint256 difficultyAmount) public {
        _run(depositAmount, betLimitAmount, difficultyAmount);
    }

    receive() external payable {}
}
